/* w3_arb.c -- rigorous evaluator of the window-3 connectivity bound (specification: ../W3.md).
 *
 *   C_k >= (1/2) int_0^inf t^{k-3/2} e^{-pi t} Phi_k^disc(t) dt,
 *   Phi_k^disc(t) = sum over product cells Q of val(H_sure(Q)) |Q| exp(-t [ubar(Z_1) + abar2(Z_1,Z_2) + sum_{i>=3} abar3(Z_{i-2},Z_{i-1},Z_i)])
 *
 * val = window-3 connectivity + local degree value (w3conn_auto.h, generated by wconn_gen.py from wconn.py).
 * Part A (FLINT arb): radial data; pair tables (S class, abar2 >= E v2: Lemma V on 3 disks, as c6idea/src/w2_arb.c);
 *         pair table LV3LO <= E[A3] (two-sided Lemma V); triple tables (T class from outer polygons; abar3 >= E v3:
 *         Lemma V on 4 disks minus LV3LO, capped by abar2; far triples (|y_{i+1} - y_{i-2}| >= 2 surely) use abar2).
 * Part B (double): forward recursion over (automaton state, previous cell, current cell), power-of-2 rescaling.
 * Part C (arb): log-convex secant t-integral with the lower incomplete gamma function (as w2_arb.c).
 *
 * usage: w3_arb N1 N2 NT DTLOG2 T KMAX NTH [NSUB]
 * env: W3FLOAT=NS (validation: sampled averages, majority classes; NOT rigorous), W3CTRL=<name> (negative controls).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <omp.h>
#include <flint/flint.h>
#include <flint/arf.h>
#include <flint/mag.h>
#include <flint/arb.h>
#include <flint/arb_hypgeom.h>
#ifndef W3AUTO
#define W3AUTO "w3conn_auto.h"
#endif
#include W3AUTO

#define PREC 128
#define ENCL 1e-7                      /* relative enclosure of the floating-point recursion */
#define PMARG 1e-12                    /* margin for double-precision polygon tests (errors are < 1e-14) */

static int N1, N2, NR, NT, ND, NC, KMAX, NTH, NSUB = 64, FLOATNS = 0;
static const char *CTRL = NULL;
static arb_t PI_, DTH, HCOS;           /* pi, pi/NT, cos(dth/2) */
static arb_ptr RB;                     /* radial grid */

/* ================= rigorous union area of n <= 4 unit disks (frozen chk_ck14 rig_union, without gradient) ================= */
#define NMAX 4
#define PMAXU 6
static double TPR; static mag_t EPS_TPR;
static void abs_ub_mag(mag_t out, const arb_t x) { arf_t u; arf_init(u); arb_get_abs_ubound_arf(u, x, 53); arf_get_mag(out, u); arf_clear(u); }
static void init_proxy_circle(void) {
  arb_t t, u; arb_init(t); arb_init(u);
  TPR = 2 * M_PI;
  arb_const_pi(t, 256); arb_mul_2exp_si(t, t, 1); arb_set_d(u, TPR); arb_sub(t, t, u, 256);
  mag_init(EPS_TPR); abs_ub_mag(EPS_TPR, t);
  arb_clear(t); arb_clear(u);
}
static void add_arc(arb_t Ai, double a, double b, double x, double y, slong prec) {
  arb_t t, sa, ca, sb, cb, u;
  arb_init(t); arb_init(sa); arb_init(ca); arb_init(sb); arb_init(cb); arb_init(u);
  arb_set_d(t, a); arb_sin_cos(sa, ca, t, prec);
  arb_set_d(u, b); arb_sin_cos(sb, cb, u, prec);
  arb_sub(u, u, t, prec);
  arb_sub(t, sb, sa, prec); arb_set_d(sa, x); arb_mul(t, t, sa, prec); arb_add(u, u, t, prec);
  arb_sub(t, ca, cb, prec); arb_set_d(sa, y); arb_mul(t, t, sa, prec); arb_add(u, u, t, prec);
  arb_mul_2exp_si(u, u, -1);
  arb_add(Ai, Ai, u, prec);
  arb_clear(t); arb_clear(sa); arb_clear(ca); arb_clear(sb); arb_clear(cb); arb_clear(u);
}
/* A = area of the union of the closed unit disks at the exact doubles (xc[i], yc[i]), i < n.  Returns 0, or -1 (undecidable). */
static int rig_unionN(arb_t A, int n, const double *xc, const double *yc, slong prec) {
  int ret = 0, has[PMAXU], rpi[PMAXU], rpj[PMAXU], rnp = 0;
  for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) { rpi[rnp] = i; rpj[rnp] = j; rnp++; }
  arb_t pi, twopi, t, u, d2, dd, Ai, cang, L, H, phi[PMAXU], alp[PMAXU];
  arb_init(pi); arb_init(twopi); arb_init(t); arb_init(u); arb_init(d2); arb_init(dd); arb_init(Ai); arb_init(cang);
  arb_init(L); arb_init(H);
  for (int p = 0; p < PMAXU; p++) { arb_init(phi[p]); arb_init(alp[p]); }
  mag_t M, rho, tm, supf; mag_init(M); mag_init(rho); mag_init(tm); mag_init(supf);
  arb_const_pi(pi, prec); arb_mul_2exp_si(twopi, pi, 1);
  for (int p = 0; p < rnp; p++) {
    has[p] = 0; int i = rpi[p], j = rpj[p];
    arb_set_d(t, xc[j]); arb_set_d(dd, xc[i]); arb_sub(t, t, dd, prec);
    arb_set_d(u, yc[j]); arb_set_d(dd, yc[i]); arb_sub(u, u, dd, prec);
    arb_sqr(d2, t, prec); arb_sqr(dd, u, prec); arb_add(d2, d2, dd, prec);
    if (arb_contains_zero(d2)) { ret = -1; goto done; }
    arb_set_ui(dd, 4);
    if (arb_ge(d2, dd)) continue;
    if (!arb_lt(d2, dd)) { ret = -1; goto done; }
    has[p] = 1;
    arb_atan2(phi[p], u, t, prec);
    arb_sqrt(dd, d2, prec); arb_mul_2exp_si(dd, dd, -1); arb_acos(alp[p], dd, prec);
  }
  arb_zero(A);
  for (int i = 0; i < n; i++) {
    double ivs[2 * NMAX], ive[2 * NMAX]; int niv = 0, narc = 0;
    mag_zero(rho);
    for (int p = 0; p < rnp; p++) {
      if (!has[p] || (rpi[p] != i && rpj[p] != i)) continue;
      narc++;
      arb_set(cang, phi[p]);
      if (rpj[p] == i) arb_add(cang, cang, pi, prec);
      arb_sub(L, cang, alp[p], prec); arb_add(H, cang, alp[p], prec);
      double lm = arf_get_d(arb_midref(L), ARF_RND_NEAR);
      int nl = 0;
      while (lm + nl * TPR < 0) nl++;
      while (lm + nl * TPR >= TPR) nl--;
      if (nl) { arb_mul_si(t, twopi, nl, prec); arb_add(L, L, t, prec); arb_add(H, H, t, prec); }
      double l2 = arf_get_d(arb_midref(L), ARF_RND_NEAR), h2 = arf_get_d(arb_midref(H), ARF_RND_NEAR);
      if (!isfinite(l2) || !isfinite(h2) || !arb_is_finite(L) || !arb_is_finite(H)) { ret = -1; goto done; }
      if (l2 < 0) l2 = 0;
      if (l2 >= TPR) l2 = nextafter(TPR, 0);
      if (h2 < l2) h2 = l2;
      if (!(h2 <= 2 * TPR)) { ret = -1; goto done; }
      arb_set_d(t, l2); arb_sub(t, L, t, prec); abs_ub_mag(tm, t); mag_add(rho, rho, tm);
      arb_set_d(t, h2); arb_sub(t, H, t, prec); abs_ub_mag(tm, t); mag_add(rho, rho, tm);
      if (h2 <= TPR) { ivs[niv] = l2; ive[niv] = h2; niv++; }
      else { ivs[niv] = l2; ive[niv] = TPR; niv++; ivs[niv] = 0; ive[niv] = h2 - TPR; niv++; }
    }
    if (narc == 0) { arb_add(A, A, pi, prec); continue; }
    mag_mul_ui(M, EPS_TPR, 1 + 4 * narc); mag_mul_ui(tm, rho, 3); mag_add(M, M, tm);
    for (int s = 1; s < niv; s++) { double a0 = ivs[s], b0 = ive[s]; int r = s - 1;
      while (r >= 0 && ivs[r] > a0) { ivs[r + 1] = ivs[r]; ive[r + 1] = ive[r]; r--; } ivs[r + 1] = a0; ive[r + 1] = b0; }
    arb_zero(Ai);
    double cur = 0;
    for (int s = 0; s < niv; s++) { if (ivs[s] > cur) add_arc(Ai, cur, ivs[s], xc[i], yc[i], prec); if (ive[s] > cur) cur = ive[s]; }
    if (cur < TPR) add_arc(Ai, cur, TPR, xc[i], yc[i], prec);
    mag_set_d(supf, fabs(xc[i])); mag_set_d(tm, fabs(yc[i])); mag_add(supf, supf, tm);
    mag_one(tm); mag_add(supf, supf, tm); mag_mul_2exp_si(supf, supf, -1);
    mag_mul(tm, M, supf); arb_add_error_mag(Ai, tm);
    arb_add(A, A, Ai, prec);
  }
done:
  arb_clear(pi); arb_clear(twopi); arb_clear(t); arb_clear(u); arb_clear(d2); arb_clear(dd); arb_clear(Ai); arb_clear(cang);
  arb_clear(L); arb_clear(H);
  for (int p = 0; p < PMAXU; p++) { arb_clear(phi[p]); arb_clear(alp[p]); }
  mag_clear(M); mag_clear(rho); mag_clear(tm); mag_clear(supf);
  return ret;
}

/* ================= helpers (as w2_arb.c) ================= */
static double up_d(const arb_t x) { arf_t u; arf_init(u); arb_get_ubound_arf(u, x, PREC); double d = arf_get_d(u, ARF_RND_UP); arf_clear(u); return d; }
static double lo_d(const arb_t x) { arf_t u; arf_init(u); arb_get_lbound_arf(u, x, PREC); double d = arf_get_d(u, ARF_RND_DOWN); arf_clear(u); return d; }
static void set_lbound(arb_t x) { arf_t l; arf_init(l); arb_get_lbound_arf(l, x, PREC); arb_set_arf(x, l); arf_clear(l); }
static void set_ubound(arb_t x) { arf_t l; arf_init(l); arb_get_ubound_arf(l, x, PREC); arb_set_arf(x, l); arf_clear(l); }
static void ucres_lt2(arb_t res, const arb_t d) {    /* u(d) for a ball d < 2 */
  arb_t h, s; arb_init(h); arb_init(s);
  arb_mul_2exp_si(h, d, -1); arb_acos(s, h, PREC); arb_mul_2exp_si(s, s, 1);
  arb_sub(res, PI_, s, PREC);
  arb_mul(s, d, d, PREC); arb_neg(s, s); arb_add_ui(s, s, 4, PREC); arb_sqrt(s, s, PREC); arb_mul(s, s, h, PREC);
  arb_add(res, res, s, PREC);
  arb_clear(h); arb_clear(s);
}
static void ucres(arb_t res, const arb_t d) {        /* u(d) = |B(z,1) \ B(0,1)|, |z| = d >= 0 (u = pi for d >= 2; u increasing) */
  arb_t two; arb_init(two); arb_set_ui(two, 2);
  if (arb_lt(d, two)) ucres_lt2(res, d);
  else if (arb_ge(d, two)) arb_set(res, PI_);
  else {                                               /* ball straddles 2: u(d) in [u(lower(d)), pi] */
    arf_t l; arf_init(l); arb_get_lbound_arf(l, d, PREC);
    arb_t dl, ul; arb_init(dl); arb_init(ul); arb_set_arf(dl, l);
    if (arb_lt(dl, two)) { ucres_lt2(ul, dl); set_lbound(ul); } else arb_set(ul, PI_);
    arb_union(res, ul, PI_, PREC);
    arb_clear(dl); arb_clear(ul); arf_clear(l);
  }
  arb_clear(two);
}
static void Eu_ring(arb_t lo, arb_t hi, const arb_t r1, const arb_t r2) {
  arb_t den, a, b, w, ua, ub, t; arb_init(den); arb_init(a); arb_init(b); arb_init(w); arb_init(ua); arb_init(ub); arb_init(t);
  arb_sqr(den, r2, PREC); arb_sqr(t, r1, PREC); arb_sub(den, den, t, PREC);
  arb_zero(lo); arb_zero(hi);
  for (int l = 0; l < NSUB; l++) {
    arb_sub(t, r2, r1, PREC); arb_mul_si(a, t, l, PREC); arb_div_si(a, a, NSUB, PREC); arb_add(a, a, r1, PREC);
    arb_mul_si(b, t, l + 1, PREC); arb_div_si(b, b, NSUB, PREC); arb_add(b, b, r1, PREC);
    arb_sqr(w, b, PREC); arb_sqr(t, a, PREC); arb_sub(w, w, t, PREC); arb_div(w, w, den, PREC);
    ucres(ua, a); ucres(ub, b);
    arb_addmul(lo, w, ua, PREC); arb_addmul(hi, w, ub, PREC);
  }
  arb_clear(den); arb_clear(a); arb_clear(b); arb_clear(w); arb_clear(ua); arb_clear(ub); arb_clear(t);
}
/* Lemma 4: range of r^2 + r'^2 + 2 r r' cos(phi), r in [r1,r2], r' in [q1,q2], cos(phi) in [cmin, cmax] */
static void frange(arb_t fmin, arb_t fmax, const arb_t r1, const arb_t r2, const arb_t q1, const arb_t q2, const arb_t cmin, const arb_t cmax) {
  arb_t f, t, one; arb_init(f); arb_init(t); arb_init(one); arb_one(one);
  const arb_struct *rr[2] = {r1, r2}, *qq[2] = {q1, q2};
  int first = 1;
  for (int a = 0; a < 2; a++) for (int b = 0; b < 2; b++) {
    arb_sqr(f, rr[a], PREC); arb_sqr(t, qq[b], PREC); arb_add(f, f, t, PREC);
    arb_mul(t, rr[a], qq[b], PREC); arb_mul(t, t, cmax, PREC); arb_mul_2exp_si(t, t, 1); arb_add(t, f, t, PREC);
    if (first) arb_set(fmax, t); else arb_max(fmax, fmax, t, PREC);
    arb_mul(t, rr[a], qq[b], PREC); arb_mul(t, t, cmin, PREC); arb_mul_2exp_si(t, t, 1); arb_add(t, f, t, PREC);
    if (first) arb_set(fmin, t); else arb_min(fmin, fmin, t, PREC);
    first = 0;
  }
  if (!arb_is_nonnegative(cmin)) {
    arb_t one_c2, x; arb_init(one_c2); arb_init(x);
    arb_sqr(one_c2, cmin, PREC); arb_sub(one_c2, one, one_c2, PREC);
    const arb_struct *fixed[4] = {r1, r2, q1, q2}, *olo[4] = {q1, q1, r1, r1}, *ohi[4] = {q2, q2, r2, r2};
    for (int e = 0; e < 4; e++) {
      arb_mul(x, cmin, fixed[e], PREC); arb_neg(x, x);
      if (arb_lt(x, olo[e]) || arb_gt(x, ohi[e])) continue;
      arb_sqr(t, fixed[e], PREC); arb_mul(t, t, one_c2, PREC);
      arb_min(fmin, fmin, t, PREC);
    }
    arb_clear(one_c2); arb_clear(x);
  }
  arb_clear(f); arb_clear(t); arb_clear(one);
}
static void cosrange(arb_t cmin, arb_t cmax, int d) {   /* cos range of phi in [(d-1) dth, (d+1) dth] */
  int ad = abs(d); arb_t t; arb_init(t);
  if (ad <= 1) arb_one(cmax); else { arb_mul_si(t, DTH, ad - 1, PREC); arb_cos(cmax, t, PREC); }
  arb_mul_si(t, DTH, ad + 1, PREC); arb_cos(cmin, t, PREC);
  arb_clear(t);
}

/* ================= per-ring data ================= */
static double *AREA_LO, *UBAR_UP; static int *NFLAG;
static arb_ptr EA2LO, RHOC, MOM, SQM;   /* E[pi + u(|z|)] lower; centroid radius; E|z - C|^2 (upper); sqrt(MOM) (upper) */

/* outer polygon of the convex hull of polar cell (ir, angular slot j = [j dth, (j+1) dth]): 5 vertices (doubles) */
static double *PVX, *PVY;              /* [(ir * (4 NT + 1) + (j + 2 NT)) * 5 + v] */
#define PVI(ir, j, v) ((((size_t)(ir) * (4 * NT + 1) + ((j) + 2 * NT)) * 5) + (v))

/* Lemma V remainder of one pair: 2 [c_r EX2 + c0 EX + min(EX2/d-, pi EX)] (at most two vertices per pair), added to Er.
   Returns 0, or -1 if d- <= 0 while d- < 2. */
static int lv_pair(arb_t Er, const arb_t dmn, const arb_t dmx, const arb_t EX, const arb_t EX2) {
  arb_t t, u, w, cr, c0, Et, two, four, one; arb_init(t); arb_init(u); arb_init(w); arb_init(cr); arb_init(c0); arb_init(Et);
  arb_init(two); arb_init(four); arb_init(one); arb_set_ui(two, 2); arb_set_ui(four, 4); arb_one(one);
  int ret = 0;
  if (arb_ge(dmn, two)) goto out;                      /* no vertex */
  if (!arb_is_positive(dmn)) { ret = -1; goto out; }
  {
    double dmaxd = arf_get_d(arb_midref(dmx), ARF_RND_NEAR);
    arb_sqr(w, dmx, PREC);
    if (dmaxd < 1.98 && arb_lt(w, four)) { arb_sub(t, four, w, PREC); arb_sqrt(t, t, PREC); arb_inv(cr, t, PREC); arb_zero(c0); }
    else {
      arb_zero(cr);
      arb_mul_2exp_si(t, dmx, -1);
      if (arb_lt(t, one)) arb_asin(u, t, PREC); else arb_mul_2exp_si(u, PI_, -1);
      arb_mul_2exp_si(t, dmn, -1);
      if (arb_lt(t, one)) arb_asin(w, t, PREC); else arb_zero(w);
      arb_sub(c0, u, w, PREC); arb_mul_2exp_si(c0, c0, 1);
    }
    arb_div(Et, EX2, dmn, PREC); arb_mul(t, PI_, EX, PREC); arb_min(Et, Et, t, PREC);
    arb_mul(t, cr, EX2, PREC); arb_addmul(t, c0, EX, PREC); arb_add(t, t, Et, PREC);
    arb_mul_2exp_si(t, t, 1);
    arb_add(Er, Er, t, PREC);
  }
out:
  arb_clear(t); arb_clear(u); arb_clear(w); arb_clear(cr); arb_clear(c0); arb_clear(Et); arb_clear(two); arb_clear(four); arb_clear(one);
  return ret;
}
/* EX, EX2 for X = sum_s w_s |z_s - C_s| + e (independent z_s): EX <= sum w_s sqrt(m_s) + e, EX2 <= (same)^2 (Minkowski) */
static void moments_X(arb_t EX, arb_t EX2, int nw, const int *w, const int *irs, const arb_t e) {
  arb_set(EX, e);
  for (int q = 0; q < nw; q++) if (w[q]) arb_addmul_si(EX, SQM + irs[q], w[q], PREC);
  arb_sqr(EX2, EX, PREC);
}
/* centroid of polar cell (ir, slot j): direction (j + 1/2) dth, radius RHOC[ir] */
static void cell_centroid(arb_t cx, arb_t cy, int ir, int j) {
  arb_t ang; arb_init(ang);
  arb_mul_si(ang, DTH, 2 * j + 1, PREC); arb_mul_2exp_si(ang, ang, -1);
  arb_sin_cos(cy, cx, ang, PREC); arb_mul(cx, cx, RHOC + ir, PREC); arb_mul(cy, cy, RHOC + ir, PREC);
  arb_clear(ang);
}
/* ranges of |z| over the hull of ring ir (widened by eps) */
static void hull_rrange(arb_t dmn, arb_t dmx, int ir, const arb_t eps) {
  arb_mul(dmn, RB + ir, HCOS, PREC); arb_sub(dmn, dmn, eps, PREC);
  arb_add(dmx, RB + ir + 1, eps, PREC);
}
/* ranges of |z + z'| over hulls of (ir, slot 0) and (ir2, slot d) (widened by eps) */
static void hull_sumrange(arb_t dmn, arb_t dmx, int ir, int ir2, int d, const arb_t eps) {
  arb_t r1h, q1h, cmin, cmax, hmin, hmax; arb_init(r1h); arb_init(q1h); arb_init(cmin); arb_init(cmax); arb_init(hmin); arb_init(hmax);
  arb_mul(r1h, RB + ir, HCOS, PREC); arb_mul(q1h, RB + ir2, HCOS, PREC);
  cosrange(cmin, cmax, d);
  frange(hmin, hmax, r1h, RB + ir + 1, q1h, RB + ir2 + 1, cmin, cmax);
  set_lbound(hmin); if (!arb_is_nonnegative(hmin)) arb_zero(hmin);
  arb_sqrt(dmn, hmin, PREC); arb_sub(dmn, dmn, eps, PREC);
  arb_sqrt(dmx, hmax, PREC); arb_add(dmx, dmx, eps, PREC);
  arb_clear(r1h); arb_clear(q1h); arb_clear(cmin); arb_clear(cmax); arb_clear(hmin); arb_clear(hmax);
}

/* ================= pair tables ================= */
static double *ABAR2, *LV3LO; static signed char *SCL2;     /* index ((ir * NR + ir2) * ND + d + NT - 1) */
#define P2I(ir, ir2, d) ((((size_t)(ir) * NR + (ir2)) * ND) + (size_t)((d) + NT - 1))

/* abar2(ir, ir2, d) >= E |B(z') \ (B(0) u B(-z))|, z in (ir, slot 0), z' in (ir2, slot d) (W2.md 5.5); S class on the cells */
static void pair_entry(int ir, int ir2, int d, double *abar_out, signed char *scls_out, double *lv3_out) {
  arb_t cmin, cmax, fmin, fmax, one, eps, t, u, A3, Er, EX, EX2, e0, e2, cx0, cy0, cx2, cy2, dmn, dmx;
  arb_init(cmin); arb_init(cmax); arb_init(fmin); arb_init(fmax); arb_init(one); arb_init(eps); arb_init(t); arb_init(u);
  arb_init(A3); arb_init(Er); arb_init(EX); arb_init(EX2); arb_init(e0); arb_init(e2); arb_init(cx0); arb_init(cy0);
  arb_init(cx2); arb_init(cy2); arb_init(dmn); arb_init(dmx);
  arb_one(one); arb_set_d(eps, 1e-12);
  cosrange(cmin, cmax, d);
  frange(fmin, fmax, RB + ir, RB + ir + 1, RB + ir2, RB + ir2 + 1, cmin, cmax);
  *scls_out = arb_le(fmax, one) ? 1 : 0;              /* sure adjacency; otherwise treated as absent (monotone value) */
  double best = UBAR_UP[ir2];                          /* fallback: v <= u(|z'|) */
  double lv3 = lo_d(EA2LO + ir2);                      /* fallback lower bound of E[A3] with A3 = |B(-z-z') u B(-z') u B(0)|: >= pi + E u(|z'|) */
  cell_centroid(cx0, cy0, ir, 0); cell_centroid(cx2, cy2, ir2, d);
  int irs[2] = {ir, ir2};
  /* (a) abar2: points Y0 = -z, Y1 = 0, Y2 = z' */
  {
    double xc[3], yc[3];
    xc[0] = -arf_get_d(arb_midref(cx0), ARF_RND_NEAR); yc[0] = -arf_get_d(arb_midref(cy0), ARF_RND_NEAR);
    xc[1] = 0; yc[1] = 0;
    xc[2] = arf_get_d(arb_midref(cx2), ARF_RND_NEAR); yc[2] = arf_get_d(arb_midref(cy2), ARF_RND_NEAR);
    arb_set_d(t, -xc[0]); arb_sub(t, cx0, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, -yc[0]); arb_sub(u, cy0, u, PREC); arb_sqr(u, u, PREC);
    arb_add(t, t, u, PREC); arb_sqrt(e0, t, PREC);
    arb_set_d(t, xc[2]); arb_sub(t, cx2, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, yc[2]); arb_sub(u, cy2, u, PREC); arb_sqr(u, u, PREC);
    arb_add(t, t, u, PREC); arb_sqrt(e2, t, PREC);
    int ok = (rig_unionN(A3, 3, xc, yc, PREC) == 0);
    arb_zero(Er);
    if (ok) { int w[2] = {1, 0}; moments_X(EX, EX2, 2, w, irs, e0); hull_rrange(dmn, dmx, ir, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
    if (ok) { int w[2] = {1, 1}; arb_add(t, e0, e2, PREC); moments_X(EX, EX2, 2, w, irs, t); hull_sumrange(dmn, dmx, ir, ir2, d, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
    if (ok) { int w[2] = {0, 1}; moments_X(EX, EX2, 2, w, irs, e2); hull_rrange(dmn, dmx, ir2, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
    if (ok) {
      arb_add(t, e0, e2, PREC); arb_mul_2exp_si(t, t, 1);
      arb_add(t, t, A3, PREC); arb_add(t, t, Er, PREC); arb_sub(t, t, EA2LO + ir, PREC);
      double lv = up_d(t); if (lv < best) best = lv;
    }
  }
  /* (b) LV3LO <= E[A3], A3 = |B(-z-z') u B(-z') u B(0)| (z = z_{i-1} in (ir, slot 0), z' = z_i in (ir2, slot d)):
         points P0 = -(z + z'), P1 = -z', P2 = 0; two-sided Lemma V. */
  {
    arb_t px0, py0, ep0, ep1; arb_init(px0); arb_init(py0); arb_init(ep0); arb_init(ep1);
    arb_add(px0, cx0, cx2, PREC); arb_add(py0, cy0, cy2, PREC);
    double xc[3], yc[3];
    xc[0] = -arf_get_d(arb_midref(px0), ARF_RND_NEAR); yc[0] = -arf_get_d(arb_midref(py0), ARF_RND_NEAR);
    xc[1] = -arf_get_d(arb_midref(cx2), ARF_RND_NEAR); yc[1] = -arf_get_d(arb_midref(cy2), ARF_RND_NEAR);
    xc[2] = 0; yc[2] = 0;
    arb_set_d(t, -xc[0]); arb_sub(t, px0, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, -yc[0]); arb_sub(u, py0, u, PREC); arb_sqr(u, u, PREC);
    arb_add(t, t, u, PREC); arb_sqrt(ep0, t, PREC);
    arb_set_d(t, -xc[1]); arb_sub(t, cx2, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, -yc[1]); arb_sub(u, cy2, u, PREC); arb_sqr(u, u, PREC);
    arb_add(t, t, u, PREC); arb_sqrt(ep1, t, PREC);
    int ok = (rig_unionN(A3, 3, xc, yc, PREC) == 0);
    arb_zero(Er);
    /* pair (P0,P1): distance |z|, X <= |dz| + 2|dz'| + ep0 + ep1 */
    if (ok) { int w[2] = {1, 2}; arb_add(t, ep0, ep1, PREC); moments_X(EX, EX2, 2, w, irs, t); hull_rrange(dmn, dmx, ir, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
    /* pair (P0,P2): distance |z + z'|, X <= |dz| + |dz'| + ep0 */
    if (ok) { int w[2] = {1, 1}; moments_X(EX, EX2, 2, w, irs, ep0); hull_sumrange(dmn, dmx, ir, ir2, d, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
    /* pair (P1,P2): distance |z'|, X <= |dz'| + ep1 */
    if (ok) { int w[2] = {0, 1}; moments_X(EX, EX2, 2, w, irs, ep1); hull_rrange(dmn, dmx, ir2, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
    if (ok) {
      arb_add(t, ep0, ep1, PREC); arb_mul_2exp_si(t, t, 1);      /* |linear term| <= 2 sum |C_j - Ct_j| */
      arb_sub(t, A3, t, PREC); arb_sub(t, t, Er, PREC);
      double l3 = lo_d(t); if (l3 > lv3) lv3 = l3;
    }
    arb_clear(px0); arb_clear(py0); arb_clear(ep0); arb_clear(ep1);
  }
  if (best < 0) { fprintf(stderr, "negative abar2 bound at (%d,%d,%d): %g\n", ir, ir2, d, best); exit(5); }
  *abar_out = best; *lv3_out = lv3;
  arb_clear(cmin); arb_clear(cmax); arb_clear(fmin); arb_clear(fmax); arb_clear(one); arb_clear(eps); arb_clear(t); arb_clear(u);
  arb_clear(A3); arb_clear(Er); arb_clear(EX); arb_clear(EX2); arb_clear(e0); arb_clear(e2); arb_clear(cx0); arb_clear(cy0);
  arb_clear(cx2); arb_clear(cy2); arb_clear(dmn); arb_clear(dmx);
}

/* ================= triple tables ================= */
static float *ABAR3; static signed char *SCL3;   /* index (((ira * NR + irb) * NR + irc) * ND + dab + NT - 1) * ND + dbc + NT - 1 */
/* layout [ib][ic][dbc][ia][dab]: for fixed (Z_b, Z_c) the entries over Z_a form one contiguous block of NR * ND */
#define T3BLK(ib, ic, dbc) (((((size_t)(ib) * NR + (ic)) * ND) + (size_t)((dbc) + NT - 1)) * (size_t)NR * ND)
#define T3I(ia, ib, ic, dab, dbc) (T3BLK(ib, ic, dbc) + (size_t)(ia) * ND + (size_t)((dab) + NT - 1))
static long long n3far = 0, n3lv = 0, n3fb = 0, n3t1 = 0;

/* max and (separating-direction) lower bound of |z_a + z_b + z_c| over the outer polygons; doubles with margin PMARG */
static void tri_range(double *mn, double *mx, int ia, int ja, int ib, int jb, int ic, int jc) {
  const double *ax = PVX + PVI(ia, ja, 0), *ay = PVY + PVI(ia, ja, 0), *bx = PVX + PVI(ib, jb, 0), *by = PVY + PVI(ib, jb, 0);
  const double *cx = PVX + PVI(ic, jc, 0), *cy = PVY + PVI(ic, jc, 0);
  double m2 = 0;
  for (int p = 0; p < 5; p++) for (int q = 0; q < 5; q++) { double sx = ax[p] + bx[q], sy = ay[p] + by[q];
    for (int r = 0; r < 5; r++) { double tx = sx + cx[r], ty = sy + cy[r], v = tx * tx + ty * ty; if (v > m2) m2 = v; } }
  *mx = sqrt(m2) + PMARG;
  /* direction of the sum of the polygon vertex means */
  double ex = 0, ey = 0;
  for (int p = 0; p < 5; p++) { ex += ax[p] + bx[p] + cx[p]; ey += ay[p] + by[p] + cy[p]; }
  double nn = sqrt(ex * ex + ey * ey);
  if (!(nn > 1e-9)) { *mn = 0; return; }
  ex /= nn; ey /= nn;
  double lo = 0; const double *XS[3] = {ax, bx, cx}, *YS[3] = {ay, by, cy};
  for (int s = 0; s < 3; s++) { double m = 1e300; for (int p = 0; p < 5; p++) { double v = ex * XS[s][p] + ey * YS[s][p]; if (v < m) m = v; } lo += m; }
  lo -= PMARG;                                         /* |e| = 1 up to 1e-16; all terms are bounded by 6 */
  *mn = lo > 0 ? lo : 0;
}

static void triple_entry(int ia, int ib, int ic, int dab, int dbc, float *abar_out, signed char *t_out) {
  int ja = 0, jb = dab, jc = dab + dbc;
  double mn, mx; tri_range(&mn, &mx, ia, ja, ib, jb, ic, jc);
  *t_out = (mx <= 1.0) ? 1 : 0;
  if (*t_out) {
    #pragma omp atomic
    n3t1++;
  }
  double a2 = ABAR2[P2I(ib, ic, dbc)];
  if (mn >= 2.0) {                                     /* B(y_{i+1}) and B(y_{i-2}) disjoint for every point: v3 = v2 */
    float f = (float)a2; if ((double)f < a2) f = nextafterf(f, INFINITY);
    *abar_out = f;
    #pragma omp atomic
    n3far++;
    return;
  }
  double best = a2;
  arb_t eps, t, u, A4, Er, EX, EX2, cxa, cya, cxb, cyb, cxc, cyc, px0, py0, ep0, ep1, ep3, dmn, dmx;
  arb_init(eps); arb_init(t); arb_init(u); arb_init(A4); arb_init(Er); arb_init(EX); arb_init(EX2); arb_init(cxa); arb_init(cya);
  arb_init(cxb); arb_init(cyb); arb_init(cxc); arb_init(cyc); arb_init(px0); arb_init(py0); arb_init(ep0); arb_init(ep1); arb_init(ep3);
  arb_init(dmn); arb_init(dmx);
  arb_set_d(eps, 1e-12);
  cell_centroid(cxa, cya, ia, ja); cell_centroid(cxb, cyb, ib, jb); cell_centroid(cxc, cyc, ic, jc);
  arb_add(px0, cxa, cxb, PREC); arb_add(py0, cya, cyb, PREC);
  /* points: P0 = -(z_a + z_b), P1 = -z_b, P2 = 0, P3 = z_c */
  double xc[4], yc[4];
  xc[0] = -arf_get_d(arb_midref(px0), ARF_RND_NEAR); yc[0] = -arf_get_d(arb_midref(py0), ARF_RND_NEAR);
  xc[1] = -arf_get_d(arb_midref(cxb), ARF_RND_NEAR); yc[1] = -arf_get_d(arb_midref(cyb), ARF_RND_NEAR);
  xc[2] = 0; yc[2] = 0;
  xc[3] = arf_get_d(arb_midref(cxc), ARF_RND_NEAR); yc[3] = arf_get_d(arb_midref(cyc), ARF_RND_NEAR);
  arb_set_d(t, -xc[0]); arb_sub(t, px0, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, -yc[0]); arb_sub(u, py0, u, PREC); arb_sqr(u, u, PREC);
  arb_add(t, t, u, PREC); arb_sqrt(ep0, t, PREC);
  arb_set_d(t, -xc[1]); arb_sub(t, cxb, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, -yc[1]); arb_sub(u, cyb, u, PREC); arb_sqr(u, u, PREC);
  arb_add(t, t, u, PREC); arb_sqrt(ep1, t, PREC);
  arb_set_d(t, xc[3]); arb_sub(t, cxc, t, PREC); arb_sqr(t, t, PREC); arb_set_d(u, yc[3]); arb_sub(u, cyc, u, PREC); arb_sqr(u, u, PREC);
  arb_add(t, t, u, PREC); arb_sqrt(ep3, t, PREC);
  int irs[3] = {ia, ib, ic};
  int ok = (rig_unionN(A4, 4, xc, yc, PREC) == 0);
  arb_zero(Er);
  /* (P0,P1): |z_a|; X <= |da| + 2|db| + ep0 + ep1 */
  if (ok) { int w[3] = {1, 2, 0}; arb_add(t, ep0, ep1, PREC); moments_X(EX, EX2, 3, w, irs, t); hull_rrange(dmn, dmx, ia, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
  /* (P0,P2): |z_a + z_b|; X <= |da| + |db| + ep0 */
  if (ok) { int w[3] = {1, 1, 0}; moments_X(EX, EX2, 3, w, irs, ep0); hull_sumrange(dmn, dmx, ia, ib, dab, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
  /* (P0,P3): |z_a + z_b + z_c|; X <= |da| + |db| + |dc| + ep0 + ep3 */
  if (ok) { int w[3] = {1, 1, 1}; arb_add(t, ep0, ep3, PREC); moments_X(EX, EX2, 3, w, irs, t);
    arb_set_d(dmn, mn); arb_sub(dmn, dmn, eps, PREC); arb_set_d(dmx, mx); arb_add(dmx, dmx, eps, PREC);
    ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
  /* (P1,P2): |z_b|; X <= |db| + ep1 */
  if (ok) { int w[3] = {0, 1, 0}; moments_X(EX, EX2, 3, w, irs, ep1); hull_rrange(dmn, dmx, ib, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
  /* (P1,P3): |z_b + z_c|; X <= |db| + |dc| + ep1 + ep3 */
  if (ok) { int w[3] = {0, 1, 1}; arb_add(t, ep1, ep3, PREC); moments_X(EX, EX2, 3, w, irs, t); hull_sumrange(dmn, dmx, ib, ic, dbc, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
  /* (P2,P3): |z_c|; X <= |dc| + ep3 */
  if (ok) { int w[3] = {0, 0, 1}; moments_X(EX, EX2, 3, w, irs, ep3); hull_rrange(dmn, dmx, ic, eps); ok = (lv_pair(Er, dmn, dmx, EX, EX2) == 0); }
  if (ok) {
    /* E v3 = E A4 - E A3 <= A4(Ct) + 2 (ep0 + ep1 + ep3) + E r4 - LV3LO(ia, ib, dab) */
    arb_add(t, ep0, ep1, PREC); arb_add(t, t, ep3, PREC); arb_mul_2exp_si(t, t, 1);
    arb_add(t, t, A4, PREC); arb_add(t, t, Er, PREC);
    arb_set_d(u, LV3LO[P2I(ia, ib, dab)]); arb_sub(t, t, u, PREC);
    double lv = up_d(t); if (lv < best) best = lv;
    #pragma omp atomic
    n3lv++;
  } else {
    #pragma omp atomic
    n3fb++;
  }
  if (CTRL && !strcmp(CTRL, "noA3")) best = 0.97 * best;   /* INVALID control: shrink abar3 by 3% */
  if (best < 0) best = 0;                              /* v3 >= 0 (cannot occur for valid bounds; kept conservative) */
  float f = (float)best; if ((double)f < best) f = nextafterf(f, INFINITY);
  *abar_out = f;
  arb_clear(eps); arb_clear(t); arb_clear(u); arb_clear(A4); arb_clear(Er); arb_clear(EX); arb_clear(EX2); arb_clear(cxa); arb_clear(cya);
  arb_clear(cxb); arb_clear(cyb); arb_clear(cxc); arb_clear(cyc); arb_clear(px0); arb_clear(py0); arb_clear(ep0); arb_clear(ep1); arb_clear(ep3);
  arb_clear(dmn); arb_clear(dmx);
}

/* ================= FLOAT validation mode (W3FLOAT=NS): sampled averages, majority classes (NOT rigorous) ================= */
static double uarea_f(int n, const double *x, const double *y) {
  double total = 0;
  for (int i = 0; i < n; i++) {
    double lo[4], hi[4]; int m = 0, covered = 0;
    for (int j = 0; j < n; j++) { if (j == i) continue;
      double dx = x[j] - x[i], dy = y[j] - y[i], d = sqrt(dx * dx + dy * dy);
      if (d >= 2) continue; if (d == 0) { if (j < i) { covered = 1; break; } else continue; }
      double ph = atan2(dy, dx), a = acos(d / 2); lo[m] = ph - a; hi[m] = ph + a; m++; }
    if (covered) continue;
    double L[8], H[8]; int q = 0;
    for (int t = 0; t < m; t++) { double a0 = lo[t], b0 = hi[t];
      while (a0 < 0) { a0 += 2 * M_PI; b0 += 2 * M_PI; } while (a0 >= 2 * M_PI) { a0 -= 2 * M_PI; b0 -= 2 * M_PI; }
      if (b0 <= 2 * M_PI) { L[q] = a0; H[q] = b0; q++; } else { L[q] = a0; H[q] = 2 * M_PI; q++; L[q] = 0; H[q] = b0 - 2 * M_PI; q++; } }
    for (int s2 = 1; s2 < q; s2++) { double a0 = L[s2], b0 = H[s2]; int r = s2 - 1;
      while (r >= 0 && L[r] > a0) { L[r + 1] = L[r]; H[r + 1] = H[r]; r--; } L[r + 1] = a0; H[r + 1] = b0; }
    double cur = 0;
    for (int s2 = 0; s2 <= q; s2++) { double a0 = (s2 < q) ? L[s2] : 2 * M_PI;
      if (a0 > cur) { double t1 = cur, t2 = a0; total += 0.5 * ((t2 - t1) + x[i] * (sin(t2) - sin(t1)) - y[i] * (cos(t2) - cos(t1))); }
      if (s2 < q && H[s2] > cur) cur = H[s2]; }
  }
  return total;
}
static void sample_cell(int ir, int j, double u1, double u2, double *x, double *y) {
  double r1 = arf_get_d(arb_midref(RB + ir), ARF_RND_NEAR), r2 = arf_get_d(arb_midref(RB + ir + 1), ARF_RND_NEAR);
  double r = sqrt(r1 * r1 + u1 * (r2 * r2 - r1 * r1)), th = (j + u2) * M_PI / NT;
  *x = r * cos(th); *y = r * sin(th);
}
static void float_pair(int ir, int ir2, int d, int NS, double *abar_out, signed char *scls_out) {
  double sum = 0; int n = 0, ok = 0;
  for (int a = 0; a < NS; a++) for (int b = 0; b < NS; b++) for (int c = 0; c < NS; c++) for (int e = 0; e < NS; e++) {
    double zx, zy, wx, wy; sample_cell(ir, 0, (a + 0.5) / NS, (b + 0.5) / NS, &zx, &zy); sample_cell(ir2, d, (c + 0.5) / NS, (e + 0.5) / NS, &wx, &wy);
    double X[3] = {-zx, 0, wx}, Y[3] = {-zy, 0, wy};
    sum += uarea_f(3, X, Y) - uarea_f(2, X, Y); n++;
    double sx = zx + wx, sy = zy + wy; if (sx * sx + sy * sy <= 1.0) ok++;
  }
  *abar_out = sum / n; *scls_out = (2 * ok >= n) ? 1 : 0;
}
static void float_triple(int ia, int ib, int ic, int dab, int dbc, int NS, float *abar_out, signed char *t_out) {
  double sum = 0; int n = 0, ok = 0; unsigned long long st = 0x9E3779B97F4A7C15ULL ^ ((((unsigned long long)ia * 131 + ib) * 131 + ic) * 1000003ULL + (unsigned long long)(dab + 500) * 1009 + (dbc + 500));
  int NSAMP = NS * NS * NS * NS;
  for (int s = 0; s < NSAMP; s++) {
    double u[6];
    for (int q = 0; q < 6; q++) { st ^= st << 13; st ^= st >> 7; st ^= st << 17; u[q] = (st >> 11) * 0x1.0p-53; }
    double ax, ay, bx, by, cx, cy;
    sample_cell(ia, 0, u[0], u[1], &ax, &ay); sample_cell(ib, dab, u[2], u[3], &bx, &by); sample_cell(ic, dab + dbc, u[4], u[5], &cx, &cy);
    double X[4] = {-(ax + bx), -bx, 0, cx}, Y[4] = {-(ay + by), -by, 0, cy};
    sum += uarea_f(4, X, Y) - uarea_f(3, X, Y); n++;
    double sx = ax + bx + cx, sy = ay + by + cy; if (sx * sx + sy * sy <= 1.0) ok++;
  }
  *abar_out = (float)(sum / n); *t_out = (2 * ok >= n) ? 1 : 0;
}

/* ================= Part C: secant t-integral (as w2_arb.c) ================= */
static void seg_int(arb_t res, const arb_t s, const arb_t alpha, const arb_t beta, const arb_t a, const arb_t b) {
  /* int_a^b t^{s-1} exp(-pi t + alpha + beta t) dt, beta < pi */
  arb_t g, x, ga, gb, t; arb_init(g); arb_init(x); arb_init(ga); arb_init(gb); arb_init(t);
  arb_sub(g, PI_, beta, PREC);
  arb_mul(x, g, b, PREC); arb_hypgeom_gamma_lower(gb, s, x, 0, PREC);
  if (arb_is_zero(a)) arb_zero(ga); else { arb_mul(x, g, a, PREC); arb_hypgeom_gamma_lower(ga, s, x, 0, PREC); }
  arb_sub(t, gb, ga, PREC);
  arb_neg(x, s); arb_pow(x, g, x, PREC); arb_mul(t, t, x, PREC);
  arb_exp(x, alpha, PREC); arb_mul(res, t, x, PREC);
  arb_clear(g); arb_clear(x); arb_clear(ga); arb_clear(gb); arb_clear(t);
}

static void t_integral(const double *phim, const int *phie, int NTV, int DTL, int TT, double secs) {
  arb_t s, tot, total6, a, b, alpha, sig, x, dt; arb_init(s); arb_init(tot); arb_init(total6); arb_init(a); arb_init(b);
  arb_init(alpha); arb_init(sig); arb_init(x); arb_init(dt);
  arb_set_ui(dt, 1); arb_mul_2exp_si(dt, dt, -DTL);
  arb_zero(total6);
  arb_t le, he; arb_init(le); arb_init(he);
  arb_set_d(x, 1 - ENCL); arb_log(le, x, PREC); arb_set_d(x, 1 + ENCL); arb_log(he, x, PREC);
  for (int k = 3; k <= KMAX; k++) {
    arb_set_si(s, 2 * k - 1); arb_mul_2exp_si(s, s, -1);
    arb_ptr L = _arb_vec_init(NTV + 1), Hh = _arb_vec_init(NTV + 1);
    int okk = 1;
    for (int j = 1; j <= NTV; j++) {
      double cm = phim[k * (NTV + 1) + j]; int ce = phie[k * (NTV + 1) + j];
      if (!(cm > 0)) { okk = 0; break; }
      { arb_t l2; arb_init(l2); arb_set_d(x, cm); arb_log(x, x, PREC); arb_const_log2(l2, PREC); arb_mul_si(l2, l2, ce, PREC); arb_add(x, x, l2, PREC); arb_clear(l2); }
      arb_add(L + j, x, le, PREC); arb_add(Hh + j, x, he, PREC);
      set_lbound(L + j); set_ubound(Hh + j);
    }
    if (!okk) { printf("k=%2d: no data\n", k); _arb_vec_clear(L, NTV + 1); _arb_vec_clear(Hh, NTV + 1); continue; }
    arb_zero(tot);
    arb_zero(a); arb_set(b, dt); arb_zero(sig);
    seg_int(x, s, L + 1, sig, a, b); arb_add(tot, tot, x, PREC);
    for (int j = 1; j < NTV; j++) {
      arb_mul_si(a, dt, j, PREC); arb_mul_si(b, dt, j + 1, PREC);
      arb_t best, cand; arb_init(best); arb_init(cand);
      arb_zero(sig); seg_int(best, s, L + j + 1, sig, a, b); set_lbound(best);
      if (j >= 2) {
        arb_sub(sig, L + j, Hh + j - 1, PREC); arb_div(sig, sig, dt, PREC); set_lbound(sig);
        arb_mul(x, sig, a, PREC); arb_sub(alpha, L + j, x, PREC); set_lbound(alpha);
        if (arb_lt(sig, PI_)) { seg_int(cand, s, alpha, sig, a, b); set_lbound(cand); if (arb_gt(cand, best)) arb_set(best, cand); }
      }
      if (j + 2 <= NTV) {
        arb_sub(sig, Hh + j + 2, L + j + 1, PREC); arb_div(sig, sig, dt, PREC); set_ubound(sig);
        arb_mul(x, sig, b, PREC); arb_sub(alpha, L + j + 1, x, PREC); set_lbound(alpha);
        if (arb_lt(sig, PI_)) { seg_int(cand, s, alpha, sig, a, b); set_lbound(cand); if (arb_gt(cand, best)) arb_set(best, cand); }
      }
      arb_add(tot, tot, best, PREC);
      arb_clear(best); arb_clear(cand);
    }
    if (!(CTRL && !strcmp(CTRL, "nohalf"))) arb_mul_2exp_si(tot, tot, -1);
    arf_t l; arf_init(l); arb_get_lbound_arf(l, tot, PREC);
    printf("k=%2d: C_k >= %.10e\n", k, arf_get_d(l, ARF_RND_DOWN));
    if (k >= 6) { arb_t q; arb_init(q); arb_set_arf(q, l); arb_add(total6, total6, q, PREC); arb_clear(q); }
    arf_clear(l);
    _arb_vec_clear(L, NTV + 1); _arb_vec_clear(Hh, NTV + 1);
  }
  { arf_t l; arf_init(l); arb_get_lbound_arf(l, total6, PREC);
    printf("sum_{k=6..%d} C_k >= %.10e   (N1 %d N2 %d NT %d dt 2^-%d T %d; total %.1f s)\n", KMAX, arf_get_d(l, ARF_RND_DOWN),
           N1, N2, NT, DTL, TT, secs); arf_clear(l); }
}

int main(int argc, char **argv) {
  if (argc >= 2 && !strcmp(argv[1], "--int")) {      /* combine: w3_arb --int N1 N2 NT DTLOG2 T KMAX < PHI lines */
    if (argc < 8) { fprintf(stderr, "usage: w3_arb --int N1 N2 NT DTLOG2 T KMAX < phi.txt\n"); return 1; }
    N1 = atoi(argv[2]); N2 = atoi(argv[3]); NT = atoi(argv[4]); int DTL = atoi(argv[5]); int TT = atoi(argv[6]); KMAX = atoi(argv[7]);
    CTRL = getenv("W3CTRL");
    arb_init(PI_); arb_const_pi(PI_, PREC);
    int NTV = TT << DTL;
    double *phim = calloc((size_t)(KMAX + 1) * (NTV + 1), sizeof(double)); int *phie = calloc((size_t)(KMAX + 1) * (NTV + 1), sizeof(int));
    char *seen = calloc((size_t)(KMAX + 1) * (NTV + 1), 1);
    char line[256]; long nl = 0;
    while (fgets(line, sizeof line, stdin)) { int k, j, e; double m;
      if (sscanf(line, "PHI %d %d %la %d", &k, &j, &m, &e) != 4) continue;
      if (k < 3 || k > KMAX || j < 1 || j > NTV) continue;
      size_t q = (size_t)k * (NTV + 1) + j;
      if (seen[q] && (phim[q] != m || phie[q] != e)) { fprintf(stderr, "conflicting PHI for k=%d j=%d\n", k, j); return 3; }
      seen[q] = 1; phim[q] = m; phie[q] = e; nl++; }
    for (int k = 3; k <= KMAX; k++) for (int j = 1; j <= NTV; j++) if (!seen[(size_t)k * (NTV + 1) + j]) { fprintf(stderr, "missing PHI k=%d j=%d\n", k, j); return 3; }
    fprintf(stderr, "read %ld PHI lines\n", nl);
    t_integral(phim, phie, NTV, DTL, TT, 0);
    return 0;
  }
  if (argc < 8) { fprintf(stderr, "usage: w3_arb N1 N2 NT DTLOG2 T KMAX NTH [J0 J1 [NSUB]]\n"); return 1; }
  N1 = atoi(argv[1]); N2 = atoi(argv[2]); NT = atoi(argv[3]); int DTL = atoi(argv[4]); int TT = atoi(argv[5]);
  KMAX = atoi(argv[6]); NTH = atoi(argv[7]);
  int J0 = 1, J1 = 0; if (argc > 9) { J0 = atoi(argv[8]); J1 = atoi(argv[9]); } if (argc > 10) NSUB = atoi(argv[10]);
  omp_set_num_threads(NTH);
  CTRL = getenv("W3CTRL"); if (CTRL) fprintf(stderr, "NEGATIVE CONTROL %s (invalid; value expected to increase)\n", CTRL);
  if (getenv("W3FLOAT")) { FLOATNS = atoi(getenv("W3FLOAT")); fprintf(stderr, "FLOAT validation mode NS=%d (not rigorous)\n", FLOATNS); }
  if (KMAX > 60) { fprintf(stderr, "KMAX too large\n"); return 1; }
  if (NT % 2) { fprintf(stderr, "NT must be even (mirror symmetry)\n"); return 1; }
  NR = N1 + N2; ND = 2 * NT - 1; NC = NR * NT;
  arb_init(PI_); arb_init(DTH); arb_init(HCOS); arb_const_pi(PI_, PREC); arb_div_si(DTH, PI_, NT, PREC);
  { arb_t t; arb_init(t); arb_mul_2exp_si(t, DTH, -1); arb_cos(HCOS, t, PREC); arb_clear(t); }
  init_proxy_circle();
  RB = _arb_vec_init(NR + 1);
  for (int j = 0; j <= NR; j++) {
    if (j <= N1) { arb_set_si(RB + j, j); arb_div_si(RB + j, RB + j, N1, PREC); }
    else { arb_set_si(RB + j, j - N1); arb_div_si(RB + j, RB + j, N2, PREC); arb_add_ui(RB + j, RB + j, 1, PREC); }
  }
  AREA_LO = malloc(sizeof(double) * NR); UBAR_UP = malloc(sizeof(double) * NR); NFLAG = malloc(sizeof(int) * NR);
  EA2LO = _arb_vec_init(NR); RHOC = _arb_vec_init(NR); MOM = _arb_vec_init(NR); SQM = _arb_vec_init(NR);
  {
    arb_t t, u, lo, hi, sinc; arb_init(t); arb_init(u); arb_init(lo); arb_init(hi); arb_init(sinc);
    arb_mul_2exp_si(t, DTH, -1); arb_sin(sinc, t, PREC); arb_div(sinc, sinc, t, PREC);
    for (int ir = 0; ir < NR; ir++) {
      arb_ptr r1 = RB + ir, r2 = RB + ir + 1;
      arb_sqr(t, r2, PREC); arb_sqr(u, r1, PREC); arb_sub(t, t, u, PREC); arb_mul(t, t, DTH, PREC); arb_mul_2exp_si(t, t, -1);
      AREA_LO[ir] = lo_d(t);
      Eu_ring(lo, hi, r1, r2);
      UBAR_UP[ir] = up_d(hi);
      arb_add(EA2LO + ir, lo, PI_, PREC); set_lbound(EA2LO + ir);
      arb_pow_ui(t, r2, 3, PREC); arb_pow_ui(u, r1, 3, PREC); arb_sub(t, t, u, PREC);
      arb_sqr(u, r2, PREC); arb_sqr(lo, r1, PREC); arb_sub(u, u, lo, PREC);
      arb_div(t, t, u, PREC); arb_mul_ui(t, t, 2, PREC); arb_div_ui(t, t, 3, PREC); arb_mul(RHOC + ir, t, sinc, PREC);
      arb_sqr(t, r1, PREC); arb_sqr(u, r2, PREC); arb_add(t, t, u, PREC); arb_mul_2exp_si(t, t, -1);
      arb_sqr(u, RHOC + ir, PREC); arb_sub(MOM + ir, t, u, PREC);
      set_ubound(MOM + ir); if (!arb_is_nonnegative(MOM + ir)) arb_zero(MOM + ir);
      arb_sqrt(SQM + ir, MOM + ir, PREC); set_ubound(SQM + ir);
      NFLAG[ir] = (ir + 1 <= N1);
      if (getenv("W3DEBUG")) fprintf(stderr, "ring %d: area_lo %g ubar_up %g ea2lo %g mom %g\n", ir, AREA_LO[ir], UBAR_UP[ir], arf_get_d(arb_midref(EA2LO + ir), ARF_RND_NEAR), arf_get_d(arb_midref(MOM + ir), ARF_RND_NEAR));
    }
    arb_clear(t); arb_clear(u); arb_clear(lo); arb_clear(hi); arb_clear(sinc);
  }
  /* outer polygons */
  PVX = malloc(sizeof(double) * (size_t)NR * (4 * NT + 1) * 5); PVY = malloc(sizeof(double) * (size_t)NR * (4 * NT + 1) * 5);
  #pragma omp parallel for schedule(dynamic, 1)
  for (int ir = 0; ir < NR; ir++) {
    arb_t a1, a2, am, c, s, r, t; arb_init(a1); arb_init(a2); arb_init(am); arb_init(c); arb_init(s); arb_init(r); arb_init(t);
    for (int j = -2 * NT; j <= 2 * NT; j++) {
      arb_mul_si(a1, DTH, j, PREC); arb_mul_si(a2, DTH, j + 1, PREC); arb_add(am, a1, a2, PREC); arb_mul_2exp_si(am, am, -1);
      const arb_struct *ang[5] = {a1, a2, a1, a2, am};
      for (int v = 0; v < 5; v++) {
        if (v < 2) arb_set(r, RB + ir); else if (v < 4) arb_set(r, RB + ir + 1); else arb_div(r, RB + ir + 1, HCOS, PREC);
        arb_sin_cos(s, c, ang[v], PREC); arb_mul(c, c, r, PREC); arb_mul(s, s, r, PREC);
        PVX[PVI(ir, j, v)] = arf_get_d(arb_midref(c), ARF_RND_NEAR); PVY[PVI(ir, j, v)] = arf_get_d(arb_midref(s), ARF_RND_NEAR);
      }
    }
    arb_clear(a1); arb_clear(a2); arb_clear(am); arb_clear(c); arb_clear(s); arb_clear(r); arb_clear(t);
  }
  double t0 = omp_get_wtime();
  /* pair tables */
  size_t TS2 = (size_t)NR * NR * ND;
  ABAR2 = malloc(sizeof(double) * TS2); LV3LO = malloc(sizeof(double) * TS2); SCL2 = malloc(TS2);
  #pragma omp parallel for schedule(dynamic, 1)
  for (int pr = 0; pr < NR * NR; pr++) {
    int ir = pr / NR, ir2 = pr % NR;
    for (int d = -(NT - 1); d <= NT - 1; d++) {
      size_t idx = P2I(ir, ir2, d);
      if (FLOATNS) { float_pair(ir, ir2, d, FLOATNS, ABAR2 + idx, SCL2 + idx); LV3LO[idx] = 0; }
      else pair_entry(ir, ir2, d, ABAR2 + idx, SCL2 + idx, LV3LO + idx);
    }
  }
  /* mirror symmetry: conservative symmetrisation */
  for (int pr = 0; pr < NR * NR; pr++) for (int d = 1; d <= NT - 1; d++) {
    size_t a = (size_t)pr * ND + (d + NT - 1), b = (size_t)pr * ND + (-d + NT - 1);
    double m = ABAR2[a] > ABAR2[b] ? ABAR2[a] : ABAR2[b]; ABAR2[a] = ABAR2[b] = m;
    double l = LV3LO[a] < LV3LO[b] ? LV3LO[a] : LV3LO[b]; LV3LO[a] = LV3LO[b] = l;
    if (SCL2[a] != SCL2[b]) SCL2[a] = SCL2[b] = 0;
  }
  if (CTRL && !strcmp(CTRL, "s1")) { /* INVALID: every pair with fmin <= 1 treated as sure: emulate by majority on centroid */
    for (int pr = 0; pr < NR * NR; pr++) for (int d = -(NT - 1); d <= NT - 1; d++) {
      int ir = pr / NR, ir2 = pr % NR; double zx, zy, wx, wy; sample_cell(ir, 0, 0.5, 0.5, &zx, &zy); sample_cell(ir2, d, 0.5, 0.5, &wx, &wy);
      if ((zx + wx) * (zx + wx) + (zy + wy) * (zy + wy) <= 1.0) SCL2[P2I(ir, ir2, d)] = 1; } }
  fprintf(stderr, "pair tables: %zu entries in %.1f s\n", TS2, omp_get_wtime() - t0);
  /* triple tables */
  size_t TS3 = (size_t)NR * NR * NR * ND * ND;
  ABAR3 = malloc(sizeof(float) * TS3); SCL3 = malloc(TS3);
  if (!ABAR3 || !SCL3) { fprintf(stderr, "out of memory (triple tables %zu)\n", TS3); return 2; }
  double t1 = omp_get_wtime();
  /* slices (distributed table builds): W3SLICE="s n" computes the (ia, ib, ic) triples with pr % n == s and writes them to
     W3SAVE (header + per pr: ND*ND floats, ND*ND bytes, row-major in (dab, dbc)), then exits; W3LOAD="f1 f2 ..." reads slices
     instead of computing (every pr must be present exactly once; the grid must match). */
  int sl_s = 0, sl_n = 1; const char *ld = getenv("W3LOAD");
  if (getenv("W3SLICE")) { if (sscanf(getenv("W3SLICE"), "%d %d", &sl_s, &sl_n) != 2 || sl_n < 1 || sl_s < 0 || sl_s >= sl_n || !getenv("W3SAVE")) { fprintf(stderr, "bad W3SLICE/W3SAVE\n"); return 1; } }
  if (!ld) {
    #pragma omp parallel for schedule(dynamic, 1)
    for (int pr = 0; pr < NR * NR * NR; pr++) {
      if (pr % sl_n != sl_s) continue;
      int ia = pr / (NR * NR), ib = (pr / NR) % NR, ic = pr % NR;
      for (int dab = -(NT - 1); dab <= NT - 1; dab++) for (int dbc = -(NT - 1); dbc <= NT - 1; dbc++) {
        size_t idx = T3I(ia, ib, ic, dab, dbc);
        if (dab < 0 || (dab == 0 && dbc < 0)) continue;        /* filled by mirror symmetry below */
        if (FLOATNS) float_triple(ia, ib, ic, dab, dbc, FLOATNS, ABAR3 + idx, SCL3 + idx);
        else triple_entry(ia, ib, ic, dab, dbc, ABAR3 + idx, SCL3 + idx);
      }
    }
    for (int pr = 0; pr < NR * NR * NR; pr++) {
      if (pr % sl_n != sl_s) continue;
      int ia = pr / (NR * NR), ib = (pr / NR) % NR, ic = pr % NR;
      for (int dab = -(NT - 1); dab <= NT - 1; dab++) for (int dbc = -(NT - 1); dbc <= NT - 1; dbc++) {
        if (!(dab < 0 || (dab == 0 && dbc < 0))) continue;
        size_t a = T3I(ia, ib, ic, dab, dbc), b = T3I(ia, ib, ic, -dab, -dbc);
        ABAR3[a] = ABAR3[b]; SCL3[a] = SCL3[b];
      }
    }
    if (getenv("W3SLICE")) {
      FILE *fo = fopen(getenv("W3SAVE"), "wb"); if (!fo) { fprintf(stderr, "cannot write %s\n", getenv("W3SAVE")); return 1; }
      int hdr[8] = {0x57334c31, N1, N2, NT, sl_s, sl_n, FLOATNS, (int)sizeof(float)}; fwrite(hdr, sizeof hdr, 1, fo);
      float *rowf = malloc(sizeof(float) * ND * ND); signed char *rowt = malloc(ND * ND);
      for (int pr = 0; pr < NR * NR * NR; pr++) {
        if (pr % sl_n != sl_s) continue;
        int ia = pr / (NR * NR), ib = (pr / NR) % NR, ic = pr % NR;
        for (int dab = -(NT - 1); dab <= NT - 1; dab++) for (int dbc = -(NT - 1); dbc <= NT - 1; dbc++) {
          size_t idx = T3I(ia, ib, ic, dab, dbc); int r = (dab + NT - 1) * ND + (dbc + NT - 1); rowf[r] = ABAR3[idx]; rowt[r] = SCL3[idx]; }
        fwrite(&pr, sizeof pr, 1, fo); fwrite(rowf, sizeof(float), (size_t)ND * ND, fo); fwrite(rowt, 1, (size_t)ND * ND, fo);
      }
      if (fclose(fo) != 0) { fprintf(stderr, "write error\n"); return 1; }
      fprintf(stderr, "slice %d/%d written to %s in %.1f s (far %lld, Lemma V %lld, fallback %lld, T=1 %lld)\n", sl_s, sl_n, getenv("W3SAVE"),
              omp_get_wtime() - t1, n3far, n3lv, n3fb, n3t1);
      return 0;
    }
  } else {
    char *list = strdup(ld); char *save = NULL; long long got = 0; char *seen = calloc((size_t)NR * NR * NR, 1);
    float *rowf = malloc(sizeof(float) * ND * ND); signed char *rowt = malloc(ND * ND);
    for (char *fn = strtok_r(list, " ", &save); fn; fn = strtok_r(NULL, " ", &save)) {
      FILE *fi = fopen(fn, "rb"); if (!fi) { fprintf(stderr, "cannot read %s\n", fn); return 1; }
      int hdr[8]; if (fread(hdr, sizeof hdr, 1, fi) != 1 || hdr[0] != 0x57334c31 || hdr[1] != N1 || hdr[2] != N2 || hdr[3] != NT || hdr[6] != FLOATNS || hdr[7] != (int)sizeof(float)) { fprintf(stderr, "bad slice header %s\n", fn); return 1; }
      int pr;
      while (fread(&pr, sizeof pr, 1, fi) == 1) {
        if (pr < 0 || pr >= NR * NR * NR || pr % hdr[5] != hdr[4] || seen[pr]) { fprintf(stderr, "bad/duplicate pr %d in %s\n", pr, fn); return 1; }
        if (fread(rowf, sizeof(float), (size_t)ND * ND, fi) != (size_t)ND * ND || fread(rowt, 1, (size_t)ND * ND, fi) != (size_t)ND * ND) { fprintf(stderr, "truncated %s\n", fn); return 1; }
        seen[pr] = 1; got++;
        int ia = pr / (NR * NR), ib = (pr / NR) % NR, ic = pr % NR;
        for (int dab = -(NT - 1); dab <= NT - 1; dab++) for (int dbc = -(NT - 1); dbc <= NT - 1; dbc++) {
          size_t idx = T3I(ia, ib, ic, dab, dbc); int r = (dab + NT - 1) * ND + (dbc + NT - 1); ABAR3[idx] = rowf[r]; SCL3[idx] = rowt[r]; }
      }
      fclose(fi);
    }
    if (got != (long long)NR * NR * NR) { fprintf(stderr, "W3LOAD: %lld of %d triples present\n", got, NR * NR * NR); return 1; }
    fprintf(stderr, "triple tables loaded from slices (%lld triples)\n", got);
    free(list); free(seen); free(rowf); free(rowt);
  }
  if (CTRL && !strcmp(CTRL, "t1")) { /* INVALID: T by the centroid sum */
    for (int pr = 0; pr < NR * NR * NR; pr++) { int ia = pr / (NR * NR), ib = (pr / NR) % NR, ic = pr % NR;
      for (int dab = -(NT - 1); dab <= NT - 1; dab++) for (int dbc = -(NT - 1); dbc <= NT - 1; dbc++) {
        double ax, ay, bx, by, cx, cy; sample_cell(ia, 0, 0.5, 0.5, &ax, &ay); sample_cell(ib, dab, 0.5, 0.5, &bx, &by); sample_cell(ic, dab + dbc, 0.5, 0.5, &cx, &cy);
        double sx = ax + bx + cx, sy = ay + by + cy; if (sx * sx + sy * sy <= 1.0) SCL3[T3I(ia, ib, ic, dab, dbc)] = 1; } } }
  fprintf(stderr, "triple tables: %zu entries in %.1f s (far %lld, Lemma V %lld, fallback %lld, T=1 %lld; half computed)\n",
          TS3, omp_get_wtime() - t1, n3far, n3lv, n3fb, n3t1);
  { double mn3 = 1e300, mx3 = -1e300; long long nnan = 0, nt1 = 0;
    for (size_t q = 0; q < TS3; q++) { double v = ABAR3[q]; if (!(v == v)) { nnan++; continue; } if (v < mn3) mn3 = v; if (v > mx3) mx3 = v; nt1 += SCL3[q]; }
    double mn2 = 1e300, mx2 = -1e300; for (size_t q = 0; q < TS2; q++) { if (ABAR2[q] < mn2) mn2 = ABAR2[q]; if (ABAR2[q] > mx2) mx2 = ABAR2[q]; }
    fprintf(stderr, "abar3 range [%g, %g], NaN %lld, T=1 entries %lld; abar2 range [%g, %g]\n", mn3, mx3, nnan, nt1, mn2, mx2); }

  /* ---------------- Part B: forward recursion in double ---------------- */
  int NTV = TT << DTL;
  if (J0 < 1) J0 = 1; if (J1 < 1 || J1 > NTV) J1 = NTV;
  double *phim = calloc((size_t)(KMAX + 1) * (NTV + 1), sizeof(double)); int *phie = calloc((size_t)(KMAX + 1) * (NTV + 1), sizeof(int));
  double *Kt2 = malloc(sizeof(double) * TS2);
  float *Kt3 = malloc(sizeof(float) * TS3);
  size_t FS = (size_t)NC * NC * W3_NSTATE;
  double *F = malloc(sizeof(double) * FS), *G = malloc(sizeof(double) * FS);
  double *F1 = malloc(sizeof(double) * (size_t)NC * W3_NSTATE);
  double *clos = malloc(sizeof(double) * NC);
  size_t *off = malloc(sizeof(size_t) * (NC + 1)); size_t LCAP = 0; int *LQ = NULL; double *LV = NULL;
  size_t *goff = malloc(sizeof(size_t) * (NC + 1)); size_t GCAP = 0; short *GD = NULL; size_t *GS = NULL, *GE = NULL;
  int *ICOF = malloc(sizeof(int) * NC);      /* per previous cell ca: ira * ND - ita */
  for (int c = 0; c < NC; c++) ICOF[c] = (c / NT) * ND - (c % NT);
  if (!F || !G || !Kt3 || !Kt2) { fprintf(stderr, "out of memory (state %zu)\n", FS); return 2; }
  double tB = omp_get_wtime();
  for (int j = J0; j <= J1; j++) {
    double t = ldexp((double)j, -DTL);
    #pragma omp parallel for
    for (size_t q = 0; q < TS2; q++) { int ir2 = (int)((q / ND) % NR); Kt2[q] = AREA_LO[ir2] * exp(-t * ABAR2[q]); }
    #pragma omp parallel for schedule(static)
    for (size_t blk = 0; blk < (size_t)NR * NR * ND; blk++) {
      int ic = (int)((blk / ND) % NR); double al = AREA_LO[ic];
      float *kp = Kt3 + blk * (size_t)NR * ND; const float *ap = ABAR3 + blk * (size_t)NR * ND;
      for (size_t q = 0; q < (size_t)NR * ND; q++) { double v = al * exp(-t * (double)ap[q]); float f = (float)v; if ((double)f > v) f = nextafterf(f, 0); kp[q] = f; }
    }
    /* level 1 */
    memset(F1, 0, sizeof(double) * (size_t)NC * W3_NSTATE);
    for (int c = 0; c < NC; c++) { int ir = c / NT; int D = w3_trans[W3_INIT][NFLAG[ir]][0][0];
      if (D >= 0) F1[(size_t)c * W3_NSTATE + D] = AREA_LO[ir] * exp(-t * UBAR_UP[ir]); }
    int E = 0;
    /* level 1 -> 2 (and k = 3 closing): F[c2][c1][D] */
    memset(F, 0, sizeof(double) * FS);
    #pragma omp parallel for schedule(dynamic, 4)
    for (int c2 = 0; c2 < NC; c2++) {
      int ir2 = c2 / NT, it2 = c2 % NT, N = NFLAG[ir2]; double cl = 0;
      for (int c1 = 0; c1 < NC; c1++) {
        int ir1 = c1 / NT, it1 = c1 % NT; size_t pi2 = P2I(ir1, ir2, it2 - it1);
        double K = Kt2[pi2]; int S = SCL2[pi2];
        for (int D = 0; D < W3_NSTATE; D++) { double f = F1[(size_t)c1 * W3_NSTATE + D]; if (f == 0) continue;
          double x = f * K; int D2 = w3_trans[D][N][S][0];
          if (D2 >= 0) F[((size_t)c2 * NC + c1) * W3_NSTATE + D2] += x;
          double cv = w3_close[D][N][S][0]; if (cv > 0) cl += x * cv; }
      }
      clos[c2] = cl;
    }
    { double cs = 0; for (int c = 0; c < NC; c++) cs += clos[c]; if (3 <= KMAX) { phim[3 * (NTV + 1) + j] = cs; phie[3 * (NTV + 1) + j] = E; } }
    /* levels i >= 2: F_i[cb][ca][D] -> F_{i+1}[cc][cb][D'] via per-cb lists of nonzero (ca, D) */
    for (int i = 2; i <= KMAX - 2; i++) {
      /* per-cb lists of nonzero (ca, D), grouped by D (counting sort): group g of cb has state GDs[...] and range [GS, GS+GN) */
      #pragma omp parallel for schedule(static)
      for (int cb = 0; cb < NC; cb++) { size_t n = 0; int nd = 0; const double *Fb = F + (size_t)cb * NC * W3_NSTATE;
        int cntD[W3_NSTATE]; for (int D = 0; D < W3_NSTATE; D++) cntD[D] = 0;
        for (int ca = 0; ca < NC; ca++) for (int D = 0; D < W3_NSTATE; D++) if (Fb[(size_t)ca * W3_NSTATE + D] != 0) cntD[D]++;
        for (int D = 0; D < W3_NSTATE; D++) { n += cntD[D]; nd += (cntD[D] > 0); }
        off[cb + 1] = n; goff[cb + 1] = nd; }
      off[0] = 0; goff[0] = 0; for (int cb = 0; cb < NC; cb++) { off[cb + 1] += off[cb]; goff[cb + 1] += goff[cb]; }
      if (off[NC] > LCAP) { LCAP = off[NC] + off[NC] / 4 + 16; free(LQ); free(LV);
        LQ = malloc(sizeof(int) * LCAP); LV = malloc(sizeof(double) * LCAP);
        if (!LQ || !LV) { fprintf(stderr, "out of memory (lists %zu)\n", LCAP); return 2; } }
      if (goff[NC] > GCAP) { GCAP = goff[NC] + goff[NC] / 4 + 16; free(GD); free(GS); free(GE);
        GD = malloc(sizeof(short) * GCAP); GS = malloc(sizeof(size_t) * GCAP); GE = malloc(sizeof(size_t) * GCAP);
        if (!GD || !GS || !GE) { fprintf(stderr, "out of memory (groups %zu)\n", GCAP); return 2; } }
      #pragma omp parallel for schedule(static)
      for (int cb = 0; cb < NC; cb++) { const double *Fb = F + (size_t)cb * NC * W3_NSTATE;
        int cntD[W3_NSTATE]; size_t pos[W3_NSTATE]; for (int D = 0; D < W3_NSTATE; D++) cntD[D] = 0;
        for (int ca = 0; ca < NC; ca++) for (int D = 0; D < W3_NSTATE; D++) if (Fb[(size_t)ca * W3_NSTATE + D] != 0) cntD[D]++;
        size_t e = off[cb]; size_t gi = goff[cb];
        for (int D = 0; D < W3_NSTATE; D++) if (cntD[D]) { GD[gi] = (short)D; GS[gi] = e; GE[gi] = e + cntD[D]; pos[D] = e; e += cntD[D]; gi++; }
        for (int ca = 0; ca < NC; ca++) for (int D = 0; D < W3_NSTATE; D++) { double f = Fb[(size_t)ca * W3_NSTATE + D];
          if (f != 0) { size_t q = pos[D]++; LQ[q] = ICOF[ca]; LV[q] = f; } } }
      if (getenv("W3DEBUG") && j == J0) fprintf(stderr, "debug level %d: nonzero %zu of %zu (%.2f%%), groups %zu\n", i, off[NC], FS, 100.0 * off[NC] / FS, goff[NC]);
      /* mirror symmetry (all angles negated: slot it -> NT-1-it): F and all tables are symmetric, so only cc with
         itc >= NT/2 are computed and G[R cc][R cb] = G[cc][cb] (NT even) */
      #pragma omp parallel for schedule(dynamic, 1)
      for (int hc = 0; hc < NR * (NT / 2); hc++) {
        int irc = hc / (NT / 2), itc = NT / 2 + hc % (NT / 2), cc = irc * NT + itc, N = NFLAG[irc]; double cl = 0;
        double g[W3_NSTATE];
        for (int cb = 0; cb < NC; cb++) {
          int irb = cb / NT, itb = cb % NT, dbc = itc - itb; int S = SCL2[P2I(irb, irc, dbc)];
          const float *Kb = Kt3 + T3BLK(irb, irc, dbc); const signed char *Tb = SCL3 + T3BLK(irb, irc, dbc);
          const int shift = itb + NT - 1;
          for (int D = 0; D < W3_NSTATE; D++) g[D] = 0;
          for (size_t gi = goff[cb]; gi < goff[cb + 1]; gi++) {
            int D = GD[gi]; double a0 = 0, a1 = 0;
            const int *lq = LQ + GS[gi]; const double *lv = LV + GS[gi]; size_t ne = GE[gi] - GS[gi];
            for (size_t e = 0; e < ne; e++) { int q = lq[e] + shift; double x = lv[e] * (double)Kb[q]; if (Tb[q]) a1 += x; else a0 += x; }
            int D0 = w3_trans[D][N][S][0], D1 = w3_trans[D][N][S][1];
            if (D0 >= 0) g[D0] += a0;
            if (D1 >= 0) g[D1] += a1;
            cl += a0 * w3_close[D][N][S][0] + a1 * w3_close[D][N][S][1];
          }
          double *Gp = G + ((size_t)cc * NC + cb) * W3_NSTATE;
          for (int D = 0; D < W3_NSTATE; D++) Gp[D] = g[D];
          int ccm = irc * NT + (NT - 1 - itc), cbm = irb * NT + (NT - 1 - itb);
          double *Gm = G + ((size_t)ccm * NC + cbm) * W3_NSTATE;
          for (int D = 0; D < W3_NSTATE; D++) Gm[D] = g[D];
        }
        clos[cc] = cl; clos[irc * NT + (NT - 1 - itc)] = cl;
      }
      double cs = 0; for (int c = 0; c < NC; c++) cs += clos[c];
      int k = i + 2;
      if (k <= KMAX) { phim[k * (NTV + 1) + j] = cs; phie[k * (NTV + 1) + j] = E; }
      double mx = 0;
      #pragma omp parallel for reduction(max:mx)
      for (size_t q = 0; q < FS; q++) if (G[q] > mx) mx = G[q];
      if (mx <= 0) break;
      int e = ilogb(mx);
      #pragma omp parallel for
      for (size_t q = 0; q < FS; q++) G[q] = ldexp(G[q], -e);
      E += e;
      double *tmp = F; F = G; G = tmp;
    }
    for (int k = 3; k <= KMAX; k++) printf("PHI %d %d %a %d\n", k, j, phim[k * (NTV + 1) + j], phie[k * (NTV + 1) + j]);
    fflush(stdout);
    fprintf(stderr, "t = %g done (%.1f s)\n", t, omp_get_wtime() - tB);
  }
  if (J0 == 1 && J1 == NTV) t_integral(phim, phie, NTV, DTL, TT, omp_get_wtime() - t0);
  return 0;
}
